"},{"relativePath":"schema.ts","content":"import { z } from "zod";

/** 后端 Agent 发送的自定义事件名，必须与 data message UI 的 name 完全一致。 */
export const SALES_REPORT_EVENT = "app.sales.report";

const salesReportRowSchema = z.object({
  month: z.string().min(1),
  revenue: z.number(),
  order_count: z.number(),
});

const salesReportPayloadSchema = z.object({
  title: z.string().min(1).optional(),
  rows: z.array(salesReportRowSchema).min(1),
});

export type SalesReportRow = z.infer<typeof salesReportRowSchema>;

export type SalesReport = {
  title?: string;
  rows: SalesReportRow[];
};

export type SalesReportParseResult =
  | { success: true; report: SalesReport }
  | { success: false; reason: "invalid_json" | "invalid_shape" };

export type RevenueSortDirection = "asc" | "desc";

/**
 * 事件 value 可能是 { format, payload } 信封、payload 字符串本身，或已解析的对象，
 * 这里统一取出真正承载报表 JSON 的那一层。
 */
function resolvePayloadSource(data: unknown): unknown {
  if (typeof data === "string") {
    return data;
  }

  if (data && typeof data === "object") {
    const record = data as Record<string, unknown>;
    const payload = record.payload;
    if (typeof payload === "string") {
      return payload;
    }
    if (payload && typeof payload === "object") {
      return payload;
    }
  }

  return data;
}

export function parseSalesReport(data: unknown): SalesReportParseResult {
  const source = resolvePayloadSource(data);

  let decoded: unknown = source;
  if (typeof source === "string") {
    try {
      decoded = JSON.parse(source) as unknown;
    } catch {
      return { success: false, reason: "invalid_json" };
    }
  }

  const parsed = salesReportPayloadSchema.safeParse(decoded);
  if (!parsed.success) {
    return { success: false, reason: "invalid_shape" };
  }

  return {
    success: true,
    report: {
      title: parsed.data.title,
      rows: parsed.data.rows,
    },
  };
}

/** 按收入排序，收入相同时按月份稳定排序。 */
export function sortRowsByRevenue(
  rows: readonly SalesReportRow[],
  direction: RevenueSortDirection,
): SalesReportRow[] {
  const factor = direction === "asc" ? 1 : -1;

  return [...rows].sort((left, right) => {
    const difference = (left.revenue - right.revenue) * factor;
    if (difference !== 0) {
      return difference;
    }
    return left.month.localeCompare(right.month);
  });
}
"},{"relativePath":"index.tsx","content":"import { Fragment, useState } from "react";
import {
  defineDataMessageUI,
  useAgentUILocaleCode,
  type DataMessageUIRenderProps,
} from "@za38.03/agent-ui-plugins";
import { getProjectMessages } from "../../application/i18n/messages";
import {
  SALES_REPORT_EVENT,
  parseSalesReport,
  sortRowsByRevenue,
  type RevenueSortDirection,
} from "./schema";
import "./styles.css";

function formatAmount(value: number, localeCode: string): string {
  try {
    return new Intl.NumberFormat(localeCode).format(value);
  } catch {
    return String(value);
  }
}

export function SalesReportMessage({ data }: DataMessageUIRenderProps<unknown>) {
  const localeCode = useAgentUILocaleCode();
  const labels = getProjectMessages(localeCode).salesReport;
  const [direction, setDirection] = useState<RevenueSortDirection>("desc");
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  const parsed = parseSalesReport(data);

  if (!parsed.success) {
    return (
      <p className="sales-report__error" role="alert">
        {labels.invalid}
      </p>
    );
  }

  const { report } = parsed;
  const rows = sortRowsByRevenue(report.rows, direction);
  const nextDirection: RevenueSortDirection = direction === "asc" ? "desc" : "asc";

  return (
    <div className="sales-report" role="group" aria-label={report.title ?? labels.heading}>
      <h3 className="sales-report__title">{report.title ?? labels.heading}</h3>
      <div className="sales-report__scroll">
        <table className="sales-report__table">
          <thead>
            <tr>
              <th scope="col" className="sales-report__head">
                {labels.month}
              </th>
              <th
                scope="col"
                className="sales-report__head sales-report__head--numeric"
                aria-sort={direction === "asc" ? "ascending" : "descending"}
              >
                <button
                  type="button"
                  className="sales-report__sort"
                  onClick={() => setDirection(nextDirection)}
                  aria-label={
                    nextDirection === "asc" ? labels.sortAscending : labels.sortDescending
                  }
                >
                  <span>{labels.revenue}</span>
                  <span className="sales-report__sort-icon" aria-hidden="true">
                    {direction === "asc" ? "↑" : "↓"}
                  </span>
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const expanded = expandedMonth === row.month;
              const detailId = `sales-report-${row.month.replace(/[^a-zA-Z0-9_-]/g, "-")}-orders`;

              return (
                <Fragment key={row.month}>
                  <tr
                    className="sales-report__row"
                    data-expanded={expanded ? "true" : undefined}
                    onClick={() => setExpandedMonth(expanded ? null : row.month)}
                  >
                    <td className="sales-report__cell">
                      <button
                        type="button"
                        className="sales-report__row-toggle"
                        aria-expanded={expanded}
                        aria-controls={detailId}
                        aria-label={expanded ? labels.collapse(row.month) : labels.expand(row.month)}
                        onClick={(event) => {
                          event.stopPropagation();
                          setExpandedMonth(expanded ? null : row.month);
                        }}
                      >
                        {row.month}
                      </button>
                    </td>
                    <td className="sales-report__cell sales-report__cell--numeric">
                      {formatAmount(row.revenue, localeCode)}
                    </td>
                  </tr>
                  {expanded ? (
                    <tr className="sales-report__detail" id={detailId}>
                      <td className="sales-report__cell" colSpan={2}>
                        {labels.orders(row.order_count)}
                      </td>
                    </tr>
                  ) : null}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/** 注册到会话消息：name 必须与后端 CUSTOM 事件名一致。 */
export const salesReportMessageUI = defineDataMessageUI<unknown>({
  name: SALES_REPORT_EVENT,
  render: SalesReportMessage,
});
"},{"relativePath":"definition.ts","content":"import type { UIPluginDefinition, UIPluginManifest } from "@za38.03/agent-ui-plugins";
import manifestJson from "./manifest.json";
import { salesReportMessageUI } from "./index";

const definition: UIPluginDefinition = {
  manifest: manifestJson as UIPluginManifest,
  provides: [],
  inject: [],
  optionalInject: ["agent-ui.locale"],
  dataMessageUIs: [salesReportMessageUI],
  Component: () => null,
};

export default definition;
"},{"relativePath":"styles.css","content":".sales-report {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: var(--foreground);
  font-size: 13px;
  line-height: 1.5;
}

.sales-report__title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  word-break: break-word;
}

.sales-report__scroll {
  width: 100%;
  min-width: 0;
  overflow-x: auto;
}

.sales-report__table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.sales-report__head {
  padding: 6px 8px;
  text-align: left;
  font-weight: 600;
  color: var(--muted-foreground);
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}

.sales-report__head--numeric,
.sales-report__cell--numeric {
  text-align: right;
}

.sales-report__sort {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 4px;
  margin: -2px -4px;
  border: none;
  border-radius: 4px;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.sales-report__sort:hover {
  background: var(--accent);
}

.sales-report__sort-icon {
  font-size: 11px;
}

.sales-report__row {
  cursor: pointer;
}

.sales-report__row:hover {
  background: var(--muted);
}

.sales-report__row[data-expanded="true"] {
  background: var(--muted);
}

.sales-report__cell {
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.sales-report__row-toggle {
  padding: 0;
  border: none;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  text-decoration: underline dotted;
  text-underline-offset: 3px;
  cursor: pointer;
}

.sales-report__detail .sales-report__cell {
  padding-top: 2px;
  color: var(--muted-foreground);
  background: var(--muted);
}

.sales-report__sort:focus-visible,
.sales-report__row-toggle:focus-visible,
.sales-report__row:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.sales-report__error {
  margin: 0;
  color: var(--destructive, #dc2626);
  font-size: 13px;
  line-height: 1.5;
}

@media (max-width: 480px) {
  .sales-report {
    font-size: 12px;
  }

  .sales-report__head,
  .sales-report__cell {
    padding: 4px 6px;
  }
}
"}]}

{"pluginId":"sales-report-message","changes":[{"type":"edit","relativePath":"index.tsx","edits":[{"oldText":"import { getProjectMessages } from "../../application/i18n/messages";","newText":"import { getSalesReportMessages } from "./i18n";"}]},{"type":"create","relativePath":"i18n.ts","content":"import type { AgentUILocaleCode } from "@za38.03/agent-ui-plugins";

export type SalesReportMessages = {
  heading: string;
  invalid: string;
  month: string;
  revenue: string;
  orders: (count: number) => string;
  sortAscending: string;
  sortDescending: string;
  expand: (month: string) => string;
  collapse: (month: string) => string;
};

/** 统一领域文案：en-US 与 zh-CN 必须保持同构。 */
const messages: Record<AgentUILocaleCode, SalesReportMessages> = {
  "zh-CN": {
    heading: "月度销售",
    invalid: "报表数据格式不正确，暂时无法展示这张销售报表。",
    month: "月份",
    revenue: "收入",
    orders: (count: number) => `订单数：${count}`,
    sortAscending: "按收入升序排列",
    sortDescending: "按收入降序排列",
    expand: (month: string) => `查看 ${month} 的订单数量`,
    collapse: (month: string) => `收起 ${month} 的订单数量`,
  },
  "en-US": {
    heading: "Monthly sales",
    invalid: "The sales report data is not in a supported format.",
    month: "Month",
    revenue: "Revenue",
    orders: (count: number) => `Orders: ${count}`,
    sortAscending: "Sort by revenue, ascending",
    sortDescending: "Sort by revenue, descending",
    expand: (month: string) => `Show order count for ${month}`,
    collapse: (month: string) => `Hide order count for ${month}`,
  },
};

export function getSalesReportMessages(localeCode: AgentUILocaleCode): SalesReportMessages {
  return messages[localeCode] ?? messages["zh-CN"];
}
