{"ok":true,"result":{"path":"/src/agent-ui/plugins/sales-report-message/schema.ts","content":"1: import { z } from "zod";
2: 
3: /** 后端 Agent 发送的自定义事件名，必须与 data message UI 的 name 完全一致。 */
4: export const SALES_REPORT_EVENT = "app.sales.report";
5: 
6: const salesReportRowSchema = z.object({
7:   month: z.string().min(1),
8:   revenue: z.number(),
9:   order_count: z.number(),
10: });
11: 
12: const salesReportPayloadSchema = z.object({
13:   title: z.string().min(1).optional(),
14:   rows: z.array(salesReportRowSchema).min(1),
15: });
16: 
17: export type SalesReportRow = z.infer<typeof salesReportRowSchema>;
18: 
19: export type SalesReport = {
20:   title?: string;
21:   rows: SalesReportRow[];
22: };
23: 
24: export type SalesReportParseResult =
25:   | { success: true; report: SalesReport }
26:   | { success: false; reason: "invalid_json" | "invalid_shape" };
27: 
28: export type RevenueSortDirection = "asc" | "desc";
29: 
30: /**
31:  * 事件 value 可能是 { format, payload } 信封、payload 字符串本身，或已解析的对象，
32:  * 这里统一取出真正承载报表 JSON 的那一层。
33:  */
34: function resolvePayloadSource(data: unknown): unknown {
35:   if (typeof data === "string") {
36:     return data;
37:   }
38: 
39:   if (data && typeof data === "object") {
40:     const record = data as Record<string, unknown>;
41:     const payload = record.payload;
42:     if (typeof payload === "string") {
43:       return payload;
44:     }
45:     if (payload && typeof payload === "object") {
46:       return payload;
47:     }
48:   }
49: 
50:   return data;
51: }
52: 
53: export function parseSalesReport(data: unknown): SalesReportParseResult {
54:   const source = resolvePayloadSource(data);
55: 
56:   let decoded: unknown = source;
57:   if (typeof source === "string") {
58:     try {
59:       decoded = JSON.parse(source) as unknown;
60:     } catch {
61:       return { success: false, reason: "invalid_json" };
62:     }
63:   }
64: 
65:   const parsed = salesReportPayloadSchema.safeParse(decoded);
66:   if (!parsed.success) {
67:     return { success: false, reason: "invalid_shape" };
68:   }
69: 
70:   return {
71:     success: true,
72:     report: {
73:       title: parsed.data.title,
74:       rows: parsed.data.rows,
75:     },
76:   };
77: }
78: 
79: /** 按收入排序，收入相同时按月份稳定排序。 */
80: export function sortRowsByRevenue(
81:   rows: readonly SalesReportRow[],
82:   direction: RevenueSortDirection,
83: ): SalesReportRow[] {
84:   const factor = direction === "asc" ? 1 : -1;
85: 
86:   return [...rows].sort((left, right) => {
87:     const difference = (left.revenue - right.revenue) * factor;
88:     if (difference !== 0) {
89:       return difference;
90:     }
91:     return left.month.localeCompare(right.month);
92:   });
93: }
