--- a/src/agent-ui/plugins/sales-report-message/schema.ts
+++ b/src/agent-ui/plugins/sales-report-message/schema.ts
@@ -1,1 +1,94 @@
-
+import { z } from "zod";
+
+/** 后端 Agent 发送的自定义事件名，必须与 data message UI 的 name 完全一致。 */
+export const SALES_REPORT_EVENT = "app.sales.report";
+
+const salesReportRowSchema = z.object({
+  month: z.string().min(1),
+  revenue: z.number(),
+  order_count: z.number(),
+});
+
+const salesReportPayloadSchema = z.object({
+  title: z.string().min(1).optional(),
+  rows: z.array(salesReportRowSchema).min(1),
+});
+
+export type SalesReportRow = z.infer<typeof salesReportRowSchema>;
+
+export type SalesReport = {
+  title?: string;
+  rows: SalesReportRow[];
+};
+
+export type SalesReportParseResult =
+  | { success: true; report: SalesReport }
+  | { success: false; reason: "invalid_json" | "invalid_shape" };
+
+export type RevenueSortDirection = "asc" | "desc";
+
+/**
+ * 事件 value 可能是 { format, payload } 信封、payload 字符串本身，或已解析的对象，
+ * 这里统一取出真正承载报表 JSON 的那一层。
+ */
+function resolvePayloadSource(data: unknown): unknown {
+  if (typeof data === "string") {
+    return data;
+  }
+
+  if (data && typeof data === "object") {
+    const record = data as Record<string, unknown>;
+    const payload = record.payload;
+    if (typeof payload === "string") {
+      return payload;
+    }
+    if (payload && typeof payload === "object") {
+      return payload;
+    }
+  }
+
+  return data;
+}
+
+export function parseSalesReport(data: unknown): SalesReportParseResult {
+  const source = resolvePayloadSource(data);
+
+  let decoded: unknown = source;
+  if (typeof source === "string") {
+    try {
+      decoded = JSON.parse(source) as unknown;
+    } catch {
+      return { success: false, reason: "invalid_json" };
+    }
+  }
+
+  const parsed = salesReportPayloadSchema.safeParse(decoded);
+  if (!parsed.success) {
+    return { success: false, reason: "invalid_shape" };
+  }
+
+  return {
+    success: true,
+    report: {
+      title: parsed.data.title,
+      rows: parsed.data.rows,
+    },
+  };
+}
+
+/** 按收入排序，收入相同时按月份稳定排序。 */
+export function sortRowsByRevenue(
+  rows: readonly SalesReportRow[],
+  direction: RevenueSortDirection,
+): SalesReportRow[] {
+  const factor = direction === "asc" ? 1 : -1;
+
+  return [...rows].sort((left, right) => {
+    const difference = (left.revenue - right.revenue) * factor;
+    if (difference !== 0) {
+      return difference;
+    }
+    return left.month.localeCompare(right.month);
+  });
+}
+

--- a/src/agent-ui/plugins/sales-report-message/index.tsx
+++ b/src/agent-ui/plugins/sales-report-message/index.tsx
@@ -1,1 +1,128 @@
-
+import { Fragment, useState } from "react";
+import {
+  defineDataMessageUI,
+  useAgentUILocaleCode,
+  type DataMessageUIRenderProps,
+} from "@za38.03/agent-ui-plugins";
+import { getSalesReportMessages } from "./i18n";
+import {
+  SALES_REPORT_EVENT,
+  parseSalesReport,
+  sortRowsByRevenue,
+  type RevenueSortDirection,
+} from "./schema";
+import "./styles.css";
+
+function formatAmount(value: number, localeCode: string): string {
+  try {
+    return new Intl.NumberFormat(localeCode).format(value);
+  } catch {
+    return String(value);
+  }
+}
+
+export function SalesReportMessage({ data }: DataMessageUIRenderProps<unknown>) {
+  const localeCode = useAgentUILocaleCode();
+  const labels = getSalesReportMessages(localeCode);
+  const [direction, setDirection] = useState<RevenueSortDirection>("desc");
+  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);
+
+  const parsed = parseSalesReport(data);
+
+  if (!parsed.success) {
+    return (
+      <p className="sales-report__error" role="alert">
+        {labels.invalid}
+      </p>
+    );
+  }
+
+  const { report } = parsed;
+  const rows = sortRowsByRevenue(report.rows, direction);
+  const nextDirection: RevenueSortDirection = direction === "asc" ? "desc" : "asc";
+
+  return (
+    <div className="sales-report" role="group" aria-label={report.title ?? labels.heading}>
+      <h3 className="sales-report__title">{report.title ?? labels.heading}</h3>
+      <div className="sales-report__scroll">
+        <table className="sales-report__table">
+          <thead>
+            <tr>
+              <th scope="col" className="sales-report__head">
+                {labels.month}
+              </th>
+              <th
+                scope="col"
+                className="sales-report__head sales-report__head--numeric"
+                aria-sort={direction === "asc" ? "ascending" : "descending"}
+              >
+                <button
+                  type="button"
+                  className="sales-report__sort"
+                  onClick={() => setDirection(nextDirection)}
+                  aria-label={
+                    nextDirection === "asc" ? labels.sortAscending : labels.sortDescending
+                  }
+                >
+                  <span>{labels.revenue}</span>
+                  <span className="sales-report__sort-icon" aria-hidden="true">
+                    {direction === "asc" ? "↑" : "↓"}
+                  </span>
+                </button>
+              </th>
+            </tr>
+          </thead>
+          <tbody>
+            {rows.map((row) => {
+              const expanded = expandedMonth === row.month;
+              const detailId = `sales-report-${row.month.replace(/[^a-zA-Z0-9_-]/g, "-")}-orders`;
+
+              return (
+                <Fragment key={row.month}>
+                  <tr
+                    className="sales-report__row"
+                    data-expanded={expanded ? "true" : undefined}
+                    onClick={() => setExpandedMonth(expanded ? null : row.month)}
+                  >
+                    <td className="sales-report__cell">
+                      <button
+                        type="button"
+                        className="sales-report__row-toggle"
+                        aria-expanded={expanded}
+                        aria-controls={detailId}
+                        aria-label={expanded ? labels.collapse(row.month) : labels.expand(row.month)}
+                        onClick={(event) => {
+                          event.stopPropagation();
+                          setExpandedMonth(expanded ? null : row.month);
+                        }}
+                      >
+                        {row.month}
+                      </button>
+                    </td>
+                    <td className="sales-report__cell sales-report__cell--numeric">
+                      {formatAmount(row.revenue, localeCode)}
+                    </td>
+                  </tr>
+                  {expanded ? (
+                    <tr className="sales-report__detail" id={detailId}>
+                      <td className="sales-report__cell" colSpan={2}>
+                        {labels.orders(row.order_count)}
+                      </td>
+                    </tr>
+                  ) : null}
+                </Fragment>
+              );
+            })}
+          </tbody>
+        </table>
+      </div>
+    </div>
+  );
+}
